mapper.select:
select p.id, p.shop_code, p.platform_code, p.platform_name, p.is_active, p.remark,
       p.create_user, p.create_time, p.update_user, p.update_time,
       (select count(1) from sdsorder.u_o_platform_store s
         where s.shop_code=p.shop_code and s.platform_code=p.platform_code) store_count
  from sdsorder.u_o_platform p
 where p.shop_code=#{shopCode}
and p.platform_code=#{platformCode}
and p.platform_name like concat('%',#{platformName},'%')
and p.is_active=#{isActive}
 order by p.is_active desc, p.platform_code

select p.*, (select count(1) from sdsorder.u_o_platform_store s
  where s.shop_code=p.shop_code and s.platform_code=p.platform_code) store_count
  from sdsorder.u_o_platform p where p.shop_code=#{shopCode} and p.platform_code=#{platformCode}

mapper.update:
update sdsorder.u_o_platform set platform_name=#{platformName},is_active=coalesce(#{isActive},1),
remark=#{remark},update_user=#{updateUser},update_time=sysdate()
where shop_code=#{shopCode} and id=#{id}

mapper.select:
select s.id,s.shop_code,s.platform_code,p.platform_name,s.store_code,s.store_name,s.is_active,s.remark,
       s.create_user,s.create_time,s.update_user,s.update_time
  from sdsorder.u_o_platform_store s
  join sdsorder.u_o_platform p on p.shop_code=s.shop_code and p.platform_code=s.platform_code
 where s.shop_code=#{shopCode}
and s.platform_code=#{platformCode}
and s.store_code=#{storeCode}
and s.store_name like concat('%',#{storeName},'%')
and s.is_active=#{isActive}
 order by s.is_active desc,s.platform_code,s.store_code

mapper.update:
update sdsorder.u_o_platform_store set store_name=#{storeName},is_active=coalesce(#{isActive},1),
remark=#{remark},update_user=#{updateUser},update_time=sysdate()
where shop_code=#{shopCode} and id=#{id}
